#!/usr/bin/env python3
"""Generate OpenType feature definitions for Code612."""

from __future__ import annotations

from pathlib import Path
from typing import Iterable


HEADER = """###
# OpenType Layout feature definitions
# Format: Adobe FDK for OpenType (AFDKO) version 2.5
# Generated on: 2026-6-19 15:48
# Generated by: FontLab 8.0.0
# Font path: /Users/brettw/prj/fonts/code-612/sources/vfj/Code612-Regular.vfj
# Font PostScript name: Code612-Bold
# Font copyright: Copyright (c) 2012, AIRBUS (airbus-group.com)Copyright (c) 2026 Brett Wilson
#
# Totals:
# Languagesystems: 3
# GSUB lookups: 8
# GSUB features: 3 (calt, ss01, ss02)
# GPOS lookups: 0

#
# Languagesystem definitions
#

languagesystem DFLT dflt; # Default default
languagesystem latn dflt; # Latin default
languagesystem grek dflt; # Greek default


#
# Lookup definitions
#


#
# Feature definitions
#

@aLike = [
    a aacute agrave acircumflex atilde adieresis aring
];

@eLike = [
    e eacute egrave ecircumflex edieresis
];

@iLike = [
    i iacute igrave icircumflex idieresis
    dotlessi
];

@oLike = [
    o oacute ograve ocircumflex otilde odieresis
    oslash
];

@uLike = [
    u uacute ugrave ucircumflex udieresis
];

@ALike = [
    A Aacute Agrave Acircumflex Atilde Adieresis Aring
];

@ELike = [
    E Eacute Egrave Ecircumflex Edieresis
];

@ILike = [
    I Iacute Igrave Icircumflex Idieresis
];

@OLike = [
    O Oacute Ograve Ocircumflex Otilde Odieresis
    Oslash
];

@ULike = [
    U Uacute Ugrave Ucircumflex Udieresis
];

@littleBoth = [
    @aLike @eLike @oLike @uLike
    c g m n p q r s v w x y z
];

@littleLeft = [
    @littleBoth
    d
];

@littleRight = [
    @littleBoth
    b h k
];

@fullBoth = [
    @ALike @ELike @ILike @OLike @ULike
    B C D F G H J K L M N P Q R S T V W X Y Z
    f i j l
    zero one two three four five six seven eight nine
];

@fullLeft = [
    @fullBoth
    b h k
];

@fullRight = [
    @fullBoth
    d
];

@letters = [

    # Vowels and accented variants

    @aLike @eLike @iLike @oLike @uLike

    @ALike @ELike @ILike @OLike @ULike

    # Remaining ASCII letters

    b c d f g h j k l m n p q r s t v w x y z

    B C D F G H J K L M N P Q R S T V W X Y Z

    # Digits

    zero one two three four five six seven eight nine

    # Space

    space

    # ASCII punctuation

    exclam
    quotedbl
    numbersign
    dollar
    percent
    ampersand
    quotesingle
    parenleft
    parenright
    asterisk
    plus
    comma
    hyphen
    period
    slash
    colon
    semicolon
    less
    equal
    greater
    question
    at
    bracketleft
    backslash
    bracketright
    asciicircum
    underscore
    grave
    braceleft
    bar
    braceright
    asciitilde
];
"""


HARDCODED_FEATURES = """
feature ss01 {
# GSUB feature: Stylistic Set 1
# Lookups: 1

  featureNames {
    name "Lowercase Brackets";
  };

  sub parenleft by parenleft.lc;
  sub parenright by parenright.lc;
  sub bracketleft by bracketleft.lc;
  sub bracketright by bracketright.lc;
  sub braceleft by braceleft.lc;
  sub braceright by braceright.lc;

} ss01;

feature ss02 {
# GSUB feature: Stylistic Set 2
# Lookups: 1

  featureNames {
    name "Undotted Zero";
  };

  sub zero by zero.alt;

} ss02;
"""


PUNCTUATION_GLYPHS = ("plus", "hyphen", "equals", "asciitilde", "asterisk")
GLYPH_ALIASES = {
    "equals": "equal",
}
OPERATOR_COMBINATIONS = (
    "+=",
    "-=",
    "<=",
    ">=",
    "~=",
    "++",
    "--",
    "=>",
    "*=",
    "->",
    "<-",
)
LONG_OPERATOR_COMBINATIONS = (
    "===",
    "!==",
    "!===",
)
REPEATED_SEQUENCE_GLYPHS = ("equal", "hyphen")
MAX_REPEATED_SEQUENCE_LENGTH = 8
OPERATOR_GLYPHS = {
    "+": "plus",
    "-": "hyphen",
    "<": "less",
    ">": "greater",
    "=": "equal",
    "~": "asciitilde",
    "*": "asterisk",
    "!": "exclam",
}
LOWERCASE_OUTPUTS = {
    "plus": "plus.lc",
    "hyphen": "hyphen.lc",
    "less": "less.lc",
    "greater": "greater.lc",
    "equal": "equal.lc",
    "asciitilde": "asciitilde.lc",
    "asterisk": "asterisk.lc",
    "exclam": "exclam",
}
COMPACT_LC_OUTPUTS = {
    ("equal", "greater"): ("equal.lc.rightfull", "greater.lc.leftfull"),
    ("hyphen", "greater"): ("hyphen.lc.rightfull", "greater.lc.leftfull"),
    ("less", "hyphen"): ("less.lc.rightfull", "hyphen.lc.leftfull"),
}
COMPACT_UC_OUTPUTS = {
    ("equal", "greater"): ("equal.rightfull", "greater.leftfull"),
    ("hyphen", "greater"): ("hyphen.rightfull", "greater.leftfull"),
    ("less", "hyphen"): ("less.rightfull", "hyphen.leftfull"),
}
UPPERCASE_OUTPUTS = {
    "plus": "plus.uc",
    "hyphen": "hyphen.uc",
    "equal": "equal.uc",
    "asciitilde": "asciitilde.uc",
    "asterisk": "asterisk.uc",
    "exclam": "exclam",
}
BRACKET_PAIRS = (
    ("parenleft", "parenright"),
    ("bracketleft", "bracketright"),
    ("braceleft", "braceright"),
)
MAX_BRACKET_CONTENT_LENGTH = 7
LC_FOLLOW_GLYPHS = (
    "plus",
    "hyphen",
    "less",
    "greater",
    "equal",
    "asciitilde",
    "asterisk",
    # Bracket/brace/paren follow rules are disabled for now.
    # "parenleft",
    # "parenright",
    # "bracketleft",
    # "bracketright",
    # "braceleft",
    # "braceright",
)
UC_FOLLOW_GLYPHS = (
    "plus",
    "hyphen",
    "equal",
    "asciitilde",
    "asterisk",
)
MAX_ANNOTATED_FOLLOW_LENGTH = 8


def output_path() -> Path:
    return Path(__file__).resolve().parent.parent / "sources" / "features.txt"


def glyph_name(name: str) -> str:
    return GLYPH_ALIASES.get(name, name)


def operator_glyphs(operator: str) -> tuple[str, str]:
    if len(operator) != 2:
        raise ValueError(f"expected a two-character operator, got {operator!r}")
    return (OPERATOR_GLYPHS[operator[0]], OPERATOR_GLYPHS[operator[1]])


def operator_glyph_sequence(operator: str) -> tuple[str, ...]:
    return tuple(OPERATOR_GLYPHS[character] for character in operator)


def lowercase_outputs(glyphs: tuple[str, ...]) -> tuple[str, ...]:
    return tuple(LOWERCASE_OUTPUTS.get(glyph, f"{glyph}.lc") for glyph in glyphs)


def uppercase_outputs(glyphs: tuple[str, ...]) -> tuple[str, ...]:
    return tuple(UPPERCASE_OUTPUTS.get(glyph, glyph) for glyph in glyphs)


def lowercase_output(glyph: str) -> str:
    return LOWERCASE_OUTPUTS.get(glyph, f"{glyph}.lc")


def uppercase_output(glyph: str) -> str:
    return UPPERCASE_OUTPUTS.get(glyph, glyph)


def lowercase_pair_outputs(left: str, right: str) -> tuple[str, str]:
    return COMPACT_LC_OUTPUTS.get((left, right), (f"{left}.lc", f"{right}.lc"))


def uppercase_pair_outputs(left: str, right: str) -> tuple[str, str]:
    return COMPACT_UC_OUTPUTS.get(
        (left, right),
        (UPPERCASE_OUTPUTS.get(left, left), UPPERCASE_OUTPUTS.get(right, right)),
    )


def append_lowercase_pair_rules(
    lines: list[str], left: str, right: str, left_output: str, right_output: str
) -> None:
    lines.extend(
        [
            f"  sub @littleRight {left}' {right} by {left_output};",
            f"  sub @littleRight {left_output} {right}' by {right_output};",
            f"  sub @littleRight space {left}' {right} by {left_output};",
            f"  sub @littleRight space {left_output} {right}' by {right_output};",
            f"  sub {left}' {right} @littleLeft by {left_output};",
            f"  sub {left_output} {right}' @littleLeft by {right_output};",
            f"  sub {left}' {right} space @littleLeft by {left_output};",
            f"  sub {left_output} {right}' space @littleLeft by {right_output};",
            "",
        ]
    )


def append_pair_right_full_rules(
    lines: list[str],
    left_input: str,
    right_input: str,
    left_output: str,
    right_output: str,
) -> None:
    for right_context in ("@fullLeft", "space @fullLeft"):
        if left_input != left_output:
            lines.append(
                f"  sub {left_input}' {right_input} {right_context} by {left_output};"
            )
        lines.append(
            f"  sub {left_output} {right_input}' {right_context} by {right_output};"
        )
    lines.append("")


def append_sequence_substitution_chain(
    lines: list[str],
    glyphs: tuple[str, ...],
    outputs: tuple[str, ...],
    prefix: str = "",
    suffix: str = "",
) -> None:
    current = list(glyphs)
    for index, output in enumerate(outputs):
        if current[index] == output:
            continue

        pattern = list(current)
        pattern[index] = f"{pattern[index]}'"
        parts = []
        if prefix:
            parts.append(prefix)
        parts.extend(pattern)
        if suffix:
            parts.append(suffix)
        lines.append(f"  sub {' '.join(parts)} by {output};")
        current[index] = output


def append_sequence_seed_substitution(
    lines: list[str],
    glyphs: tuple[str, ...],
    outputs: tuple[str, ...],
    prefix: str = "",
    suffix: str = "",
) -> None:
    for index, output in enumerate(outputs):
        if glyphs[index] == output:
            continue

        pattern = list(glyphs)
        pattern[index] = f"{pattern[index]}'"
        parts = []
        if prefix:
            parts.append(prefix)
        parts.extend(pattern)
        if suffix:
            parts.append(suffix)
        lines.append(f"  sub {' '.join(parts)} by {output};")
        return


def append_long_operator_right_full_rules(
    lines: list[str], glyphs: tuple[str, ...], outputs: tuple[str, ...]
) -> None:
    for suffix in ("@fullLeft", "space @fullLeft"):
        append_sequence_substitution_chain(lines, glyphs, outputs, suffix=suffix)
    lines.append("")


def append_long_operator_lowercase_rules(
    lines: list[str], glyphs: tuple[str, ...], outputs: tuple[str, ...]
) -> None:
    for prefix in ("@littleRight", "@littleRight space"):
        append_sequence_substitution_chain(lines, glyphs, outputs, prefix=prefix)
    for suffix in ("@littleLeft", "space @littleLeft"):
        append_sequence_substitution_chain(lines, glyphs, outputs, suffix=suffix)
    lines.append("")


def append_repeated_sequence_rules(
    lines: list[str],
    glyph: str,
    length: int,
    outputs: tuple[str, ...],
    right_full: bool,
) -> None:
    glyphs = tuple([glyph] * length)
    if right_full:
        for suffix in ("@fullLeft", "space @fullLeft"):
            append_sequence_seed_substitution(lines, glyphs, outputs, suffix=suffix)
    else:
        for prefix in ("@littleRight", "@littleRight space"):
            append_sequence_seed_substitution(lines, glyphs, outputs, prefix=prefix)
        for suffix in ("@littleLeft", "space @littleLeft"):
            append_sequence_seed_substitution(lines, glyphs, outputs, suffix=suffix)
    lines.append("")


def repeated_sequence_lengths() -> range:
    return range(MAX_REPEATED_SEQUENCE_LENGTH, 1, -1)


def unique_glyphs(glyphs: Iterable[str]) -> tuple[str, ...]:
    seen: set[str] = set()
    ordered: list[str] = []
    for glyph in glyphs:
        if glyph in seen:
            continue
        seen.add(glyph)
        ordered.append(glyph)
    return tuple(ordered)


def annotated_lc_glyphs() -> tuple[str, ...]:
    glyphs: list[str] = []
    glyphs.extend(
        output for glyph, output in LOWERCASE_OUTPUTS.items() if output != glyph
    )
    for left, right in COMPACT_LC_OUTPUTS.values():
        glyphs.extend((left, right))
    # Bracket/brace/paren annotated classes are disabled for now.
    # for left, right in BRACKET_PAIRS:
    #     glyphs.extend((f"{left}.lc", f"{right}.lc"))
    return unique_glyphs(glyphs)


def annotated_uc_glyphs() -> tuple[str, ...]:
    glyphs: list[str] = []
    glyphs.extend(
        output for glyph, output in UPPERCASE_OUTPUTS.items() if output != glyph
    )
    for left, right in COMPACT_UC_OUTPUTS.values():
        glyphs.extend((left, right))
    return unique_glyphs(glyphs)


def format_class_definition(name: str, glyphs: tuple[str, ...]) -> str:
    lines = [f"@{name} = ["]
    for index in range(0, len(glyphs), 4):
        lines.append(f"    {' '.join(glyphs[index:index + 4])}")
    lines.append("];")
    return "\n".join(lines)


def generate_annotated_classes() -> str:
    return "\n\n".join(
        (
            "",
            format_class_definition("lcAnnotated", annotated_lc_glyphs()),
            format_class_definition("ucAnnotated", annotated_uc_glyphs()),
            "",
        )
    )


def append_annotated_follow_rules(lines: list[str]) -> None:
    for _round in range(MAX_ANNOTATED_FOLLOW_LENGTH):
        for glyph in LC_FOLLOW_GLYPHS:
            output = lowercase_output(glyph)
            if output != glyph:
                lines.append(f"  sub @lcAnnotated {glyph}' by {output};")
        lines.append("")

        for glyph in UC_FOLLOW_GLYPHS:
            output = uppercase_output(glyph)
            if output != glyph:
                lines.append(f"  sub @ucAnnotated {glyph}' by {output};")
        lines.append("")


def bracket_context(content_length: int, close_side: bool = False) -> str:
    if content_length == 1:
        return "@littleRight" if close_side else "@littleLeft"
    middle = " ".join(["@letters"] * (content_length - 2))
    parts = ["@littleLeft"]
    if middle:
        parts.append(middle)
    parts.append("@littleRight")
    return " ".join(parts)


def append_bracket_pair_rules(lines: list[str], left: str, right: str) -> None:
    for content_length in range(1, MAX_BRACKET_CONTENT_LENGTH + 1):
        left_context = bracket_context(content_length)
        right_context = bracket_context(content_length, close_side=True)
        lines.extend(
            [
                f"  sub {left}' {left_context} {right} by {left}.lc;",
                f"  sub {left}.lc {right_context} {right}' by {right}.lc;",
            ]
        )
    lines.append("")


def generate_calt() -> str:
    lines = [
        "",
        "feature calt {",
        "# GSUB feature: Contextual Alternates",
        "# Lookups: 1",
    ]

    for glyph in REPEATED_SEQUENCE_GLYPHS:
        for length in repeated_sequence_lengths():
            glyphs = tuple([glyph] * length)
            append_repeated_sequence_rules(
                lines, glyph, length, uppercase_outputs(glyphs), right_full=True
            )

    for operator in LONG_OPERATOR_COMBINATIONS:
        glyphs = operator_glyph_sequence(operator)
        append_long_operator_right_full_rules(lines, glyphs, uppercase_outputs(glyphs))

    for operator in OPERATOR_COMBINATIONS:
        left, right = operator_glyphs(operator)
        left_output, right_output = uppercase_pair_outputs(left, right)
        append_pair_right_full_rules(lines, left, right, left_output, right_output)

    for glyph in REPEATED_SEQUENCE_GLYPHS:
        for length in repeated_sequence_lengths():
            glyphs = tuple([glyph] * length)
            append_repeated_sequence_rules(
                lines, glyph, length, lowercase_outputs(glyphs), right_full=False
            )

    for operator in LONG_OPERATOR_COMBINATIONS:
        glyphs = operator_glyph_sequence(operator)
        append_long_operator_lowercase_rules(lines, glyphs, lowercase_outputs(glyphs))

    for operator in OPERATOR_COMBINATIONS:
        left, right = operator_glyphs(operator)
        left_output, right_output = lowercase_pair_outputs(left, right)
        append_lowercase_pair_rules(lines, left, right, left_output, right_output)

    for punctuation in PUNCTUATION_GLYPHS:
        glyph = glyph_name(punctuation)
        lines.extend(
            [
                f"  sub @fullRight {glyph}' by {glyph}.uc;",
                f"  sub @fullRight space {glyph}' by {glyph}.uc;",
                f"  sub {glyph}' @fullLeft by {glyph}.uc;",
                f"  sub {glyph}' space @fullLeft by {glyph}.uc;",
                "",
                f"  sub @littleRight {glyph}' by {glyph}.lc;",
                f"  sub @littleRight space {glyph}' by {glyph}.lc;",
                f"  sub {glyph}' @littleLeft by {glyph}.lc;",
                f"  sub {glyph}' space @littleLeft by {glyph}.lc;",
                "",
            ]
        )

    append_annotated_follow_rules(lines)

    # Bracket/brace/paren pair rules are disabled for now.
    # for left, right in BRACKET_PAIRS:
    #     append_bracket_pair_rules(lines, left, right)

    lines.append("} calt;")
    return "\n".join(lines)


def generate_features() -> str:
    return f"{HEADER}{generate_annotated_classes()}{HARDCODED_FEATURES}{generate_calt()}\n"


def main() -> int:
    path = output_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(generate_features(), encoding="utf-8")
    print(f"Wrote {path}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
